class Solution:
    def findTheDifference(self, s: str, t: str) -> str:
        s, t = sorted(s), sorted(t)
        i = 0
        while i < len(s):
            if s[i] != t[i]:
                return t[i]
            i += 1

        return t[i]


s = Solution()
print(s.findTheDifference(s="abcd", t="abcde"))  # Output: "e"
print(s.findTheDifference(s="", t=""))  # Output: "e"

